import React from "react";

const VideoCallModal = ({ meetingId, passcode, joinUrl, onLeave }) => {
  const openZoom = () => {
    if (joinUrl) {
      window.open(joinUrl, "_blank");
      return;
    }
    window.open("https://zoom.us/join", "_blank");
  };

  const copyText = async (text) => {
    try {
      await navigator.clipboard.writeText(text);
      alert("Copied!");
    } catch (e) {
      alert("Copy failed");
    }
  };

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.8)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 10003
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "480px",
          background: "#0f172a",
          color: "white",
          borderRadius: "24px",
          padding: "32px",
          border: "1px solid rgba(255,255,255,0.15)",
          boxShadow: "0 20px 50px rgba(0,0,0,0.4)"
        }}
      >
        <h2 style={{ marginTop: 0, marginBottom: 16 }}>🎥 Join Zoom Lesson</h2>

        <div style={{ marginBottom: 16 }}>
          <div style={{ opacity: 0.7, marginBottom: 6 }}>Meeting ID</div>
          <div style={{ fontSize: "20px", fontWeight: 700 }}>{meetingId || "Not provided"}</div>
        </div>

        <div style={{ marginBottom: 24 }}>
          <div style={{ opacity: 0.7, marginBottom: 6 }}>Passcode</div>
          <div style={{ fontSize: "18px", fontWeight: 700 }}>{passcode || "Not provided"}</div>
        </div>

        {joinUrl && (
          <div style={{ marginBottom: 24 }}>
            <div style={{ opacity: 0.7, marginBottom: 6 }}>Invite Link</div>
            <div style={{ wordBreak: "break-all", fontSize: "14px", color: "#67e8f9" }}>
              {joinUrl}
            </div>
          </div>
        )}

        <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
          <button
            onClick={openZoom}
            style={{
              background: "linear-gradient(135deg, #2563eb, #1d4ed8)",
              color: "white",
              border: "none",
              borderRadius: "16px",
              padding: "14px 18px",
              fontWeight: 700,
              cursor: "pointer"
            }}
          >
            Open Zoom
          </button>

          {meetingId && (
            <button
              onClick={() => copyText(meetingId)}
              style={{
                background: "rgba(255,255,255,0.12)",
                color: "white",
                border: "none",
                borderRadius: "16px",
                padding: "14px 18px",
                fontWeight: 700,
                cursor: "pointer"
              }}
            >
              Copy Meeting ID
            </button>
          )}

          {passcode && (
            <button
              onClick={() => copyText(passcode)}
              style={{
                background: "rgba(255,255,255,0.12)",
                color: "white",
                border: "none",
                borderRadius: "16px",
                padding: "14px 18px",
                fontWeight: 700,
                cursor: "pointer"
              }}
            >
              Copy Passcode
            </button>
          )}

          <button
            onClick={onLeave}
            style={{
              background: "rgba(239,68,68,0.9)",
              color: "white",
              border: "none",
              borderRadius: "16px",
              padding: "14px 18px",
              fontWeight: 700,
              cursor: "pointer"
            }}
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default VideoCallModal;
